  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","word","reps","runLength","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  word: "AGAIN.",
  reps: 6,
  runLength: 42,
  fontFamily: "Archivo Narrow",
  scale: 1,
  delay: 0,
  speed: 1,
};

type RepStackElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof RepStackBase>;

const RepStackInner = forwardRef<
  HTMLDivElement,
  RepStackElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<RepStack>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <RepStackBase
          {...(componentProps as unknown as ComponentProps<typeof RepStackBase>)}
        />
      </div>
    </Sequence>
  );
});

export const RepStack = Interactive.withSchema({
  Component: RepStackInner,
  componentName: "<RepStack>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
